.hero-actions{display:flex;gap:14px}
.btn{display:inline-flex;align-items:center;padding:14px 26px;font-size:13px;font-weight:700;text-decoration:none;border-radius:4px;transition:all 0.2s;cursor:pointer;border:none;font-family:inherit;text-transform:uppercase;letter-spacing:1px}
.btn-primary{background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#000}
