.edition-canvas{width:100%;max-width:300px;height:auto;margin:0 auto 20px;display:block}
.edition-info{flex:1;display:flex;flex-direction:column}
.edition-header{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px}
.edition-header h3{font-family:Georgia,serif;font-size:30px;font-weight:400;letter-spacing:-0.3px}
.edition-tag{font-size:10px;color:var(--dim);letter-spacing:2px;text-transform:uppercase}
.edition-info p{color:var(--dim);font-size:14px;margin-bottom:22px;flex:1;line-height:1.55}
.edition-footer{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding-top:18px;border-top:1px solid var(--border)}
.price{font-family:Georgia,serif;font-size:26px;color:var(--accent);font-weight:400}
.edition-stock{font-size:11px;color:var(--dim);flex:1;letter-spacing:0.3px}
