.sold-out-badge,.coming-soon-badge{font-size:10px;font-weight:700;letter-spacing:1.8px;text-transform:uppercase;padding:7px 14px;border-radius:3px}
.sold-out-badge{background:rgba(220,80,80,0.12);color:#ff7878;border:1px solid rgba(220,80,80,0.35)}
.coming-soon-badge{background:rgba(100,150,220,0.12);color:#7ab0ff;border:1px solid rgba(100,150,220,0.35)}
